('v-ia-1', 'video', 'Como um computador "enxerga" uma foto?', 'Pixels, cores e padrões: a ideia básica por trás da visão computacional, explicada em linguagem simples.', null, null, 'ia', 'Vídeos da equipe MegaMorfose', array['visão computacional','pixels']::text[], 'iniciante', '8 min', null, null, 'published', true, true, '{"producer":"Equipe MegaMorfose"}'::jsonb),
