('v-el-1', 'video', 'Seu primeiro circuito: acendendo um LED', 'Bateria, resistor e LED: o trio que ensina como a eletricidade percorre um circuito.', null, null, 'eletronica', 'Vídeos da equipe MegaMorfose', array['LED','circuitos']::text[], 'iniciante', '10 min', null, null, 'published', true, true, '{"producer":"Equipe MegaMorfose"}'::jsonb),
('v-el-2', 'video', 'Sensores: os sentidos de um robô', 'Como sensores de distância, cor e toque ajudam um robô a perceber o mundo.', null, null, 'eletronica', 'Vídeo explicativo', array['sensores','robótica']::text[], 'intermediario', '12 min', null, null, 'published', false, true, '{}'::jsonb),
('v-me-1', 'video', 'Engrenagens: trocando força por velocidade', 'Por que uma engrenagem pequena girando uma grande deixa o movimento mais forte e mais lento.', null, null, 'mecanica', 'Vídeos da equipe MegaMorfose', array['engrenagens','transmissão']::text[], 'iniciante', '9 min', null, null, 'published', true, true, '{"producer":"Equipe MegaMorfose"}'::jsonb),
('v-me-2', 'video', 'Por dentro de um robô de competição', 'Um tour pelos mecanismos de um robô: chassi, braço, garra e sistemas de transmissão.', null, null, 'mecanica', 'Mini documentário', array['FTC','robótica']::text[], 'intermediario', '15 min', null, null, 'published', false, true, '{}'::jsonb),
('t-ia-1', 'tutorial', 'Treine um modelo que reconhece objetos (sem programar)', 'Use uma ferramenta online gratuita para ensinar o computador a diferenciar objetos com a câmera.', null, null, 'ia', 'Tutoriais da equipe', array['machine learning','sem código']::text[], 'iniciante', '30 min', null, null, 'published', false, true, '{"materials":["Computador ou celular com câmera","3 objetos diferentes"],"steps":["Abra a ferramenta de treino indicada pela equipe","Crie uma classe para cada objeto","Grave cerca de 50 fotos de cada objeto","Clique em treinar e aguarde","Teste mostrando os objetos para a câmera","Anote quando o modelo erra e pense no porquê"]}'::jsonb),
('t-ia-2', 'tutorial', 'Detectando cores com visão computacional', 'Entenda como robôs encontram objetos coloridos usando filtros de cor.', null, null, 'ia', 'Passo a passo', array['cores','robótica']::text[], 'intermediario', '45 min', null, null, 'published', false, true, '{"steps":["Entenda o que é o espaço de cores HSV","Escolha a faixa de cor do objeto","Aplique o filtro na imagem","Encontre o maior contorno","Calcule o centro do objeto"]}'::jsonb),
('t-el-1', 'tutorial', 'Montando um semáforo com 3 LEDs', 'Projeto clássico para aprender a controlar saídas com um microcontrolador.', null, null, 'eletronica', 'Tutoriais da equipe', array['Arduino','LED']::text[], 'iniciante', '40 min', null, null, 'published', false, true, '{"materials":["Placa microcontroladora (ou simulador online)","3 LEDs (vermelho, amarelo, verde)","3 resistores de 220 Ω","Jumpers e protoboard"],"steps":["Monte os LEDs na protoboard","Ligue cada LED a um pino com seu resistor","Escreva o código de liga/desliga","Ajuste os tempos de cada cor","Desafio: adicione um botão de pedestre"]}'::jsonb),
('t-el-2', 'tutorial', 'Medindo distância com sensor ultrassônico', 'Aprenda a ler um sensor e usar o valor para tomar decisões.', null, null, 'eletronica', 'Passo a passo', array['sensores']::text[], 'intermediario', '50 min', null, null, 'published', false, true, '{"steps":["Conecte o sensor à placa","Envie o pulso de disparo","Meça o tempo do eco","Converta tempo em distância","Acenda um LED quando algo chegar perto"]}'::jsonb),
('t-me-1', 'tutorial', 'Construa uma alavanca e meça a vantagem mecânica', 'Com régua, lápis e moedas, descubra como mudar o ponto de apoio muda a força necessária.', null, null, 'mecanica', 'Tutoriais da equipe', array['alavancas','experimento']::text[], 'iniciante', '25 min', null, null, 'published', false, true, '{"materials":["Régua de 30 cm","Lápis","Moedas"],"steps":["Apoie a régua sobre o lápis","Coloque moedas de um lado","Encontre quantas moedas equilibram do outro lado","Mude a posição do lápis e repita","Anote o padrão que você encontrou"]}'::jsonb),
('t-me-2', 'tutorial', 'Modelando sua primeira peça 3D', 'Do esboço ao arquivo pronto para impressão em um modelador online gratuito.', null, null, 'mecanica', 'Passo a passo', array['impressão 3D','CAD']::text[], 'iniciante', '1 h', null, null, 'published', false, true, '{"steps":["Faça um esboço em papel com medidas","Crie as formas básicas no modelador","Combine e recorte formas","Confira as medidas","Exporte o arquivo STL"]}'::jsonb),
