('sg-1', 'school_guide', 'Como fundar um clube de robótica', 'Do grupo de amigos interessados ao primeiro robô, passo a passo.', 'Um clube de robótica começa com poucas pessoas e um objetivo claro. Não é preciso ter kits caros: dá para começar com simuladores, sucata e muita curiosidade.', null, 'geral', 'Clubes', array[]::text[], null, '10 min', null, null, 'published', true, false, '{"steps":["Reúna 3 a 5 colegas interessados","Escreva em uma página o objetivo do clube","Convide um professor para orientar","Apresente a proposta à direção","Defina dia, horário e local dos encontros","Comece com projetos simples e baratos","Registre e divulgue os resultados"],"checklist":["Grupo inicial","Professor orientador","Proposta escrita","Autorização da escola","Calendário","Primeiro projeto"]}'::jsonb),
('sg-2', 'school_guide', 'Como iniciar um clube de programação', 'Encontros semanais, desafios curtos e projetos em grupo.', 'Um clube de programação precisa de computadores (ou celulares) e uma rotina. Alterne encontros de aprendizado, de desafio e de projeto.', null, 'geral', 'Clubes', array[]::text[], null, '8 min', null, null, 'published', false, false, '{"steps":["Verifique acesso a computadores","Escolha uma linguagem ou ferramenta para iniciantes","Monte um calendário de 8 encontros","Proponha um desafio por semana","Termine com um projeto em grupo"]}'::jsonb),
('sg-3', 'school_guide', 'Como organizar um grupo de estudos', 'Metas claras, encontros curtos e revezamento de quem explica.', null, null, 'geral', 'Organização', array[]::text[], null, '5 min', null, null, 'published', false, false, '{"steps":["Defina o objetivo (prova, olimpíada, tema)","Combine frequência e duração","Reveze quem prepara a explicação","Use listas de exercícios","Avalie o progresso a cada mês"]}'::jsonb),
('sg-4', 'school_guide', 'Como organizar uma feira de ciências', 'Planejamento, inscrições de projetos, avaliação e divulgação.', null, null, 'geral', 'Eventos', array[]::text[], null, '10 min', null, null, 'published', false, false, '{"steps":["Monte uma comissão com estudantes e professores","Defina data, local e regras","Abra inscrições de projetos","Ofereça orientação aos grupos","Organize avaliadores","Divulgue para famílias e comunidade"],"checklist":["Comissão","Regulamento","Ficha de inscrição","Ficha de avaliação","Mapa do espaço","Divulgação"]}'::jsonb),
('sg-5', 'school_guide', 'Como encontrar professores orientadores', 'Quem procurar e como fazer o convite.', 'Procure professores de ciências, matemática, física, informática ou qualquer docente que demonstre interesse. Leve uma proposta curta: objetivo, frequência dos encontros e como o professor pode ajudar. Mostre que o grupo está comprometido.', null, 'geral', 'Organização', array[]::text[], null, '4 min', null, null, 'published', false, false, '{}'::jsonb),
('sg-6', 'school_guide', 'Como apresentar um projeto à direção da escola', 'Uma proposta curta, objetiva e com benefícios claros para a escola.', null, null, 'geral', 'Organização', array[]::text[], null, '6 min', null, null, 'published', false, false, '{"steps":["Explique o problema ou oportunidade","Mostre o objetivo e as atividades","Diga quem participa e quem orienta","Liste o que precisa (espaço, horário, materiais)","Mostre os benefícios para a escola","Peça uma reunião curta"]}'::jsonb),
('sg-7', 'school_guide', 'Como conseguir integrantes e organizar reuniões', 'Divulgação, pauta, registro e divisão de tarefas.', null, null, 'geral', 'Organização', array[]::text[], null, '6 min', null, null, 'published', false, false, '{"steps":["Faça uma demonstração aberta","Use cartazes e grupos da escola","Tenha pauta para cada reunião","Registre decisões e responsáveis","Celebre pequenas conquistas"]}'::jsonb),
('sg-8', 'school_guide', 'Como encontrar parceiros e patrocínios', 'Empresas locais, universidades e a própria comunidade podem ajudar.', 'Patrocínio é uma troca: a equipe recebe recursos e o parceiro recebe visibilidade e impacto social. Monte uma apresentação curta com quem vocês são, o que fazem, o que precisam e o que oferecem em troca.', null, 'geral', 'Parcerias', array[]::text[], null, '8 min', null, null, 'published', false, false, '{"steps":["Liste empresas e instituições da região","Prepare uma apresentação de 1 página","Peça ajuda ao professor orientador para o contato","Ofereça contrapartidas (logo, relatório, demonstração)","Agradeça e preste contas"]}'::jsonb),
