('ch-2026-11', 'challenge', 'Desafio de novembro: a ponte de palitos', 'Construa uma ponte só com palitos e cola que aguente o maior peso possível.', 'Use triângulos! Eles são a forma mais rígida em estruturas. Registre quanto peso sua ponte aguentou e compartilhe na Vitrine.', null, 'mecanica', null, array[]::text[], 'iniciante', '2 h', null, null, 'published', true, true, '{"month":"2026-11","materials":["Palitos de picolé ou de dente","Cola branca","Livros ou garrafas para pesar"],"steps":["Desenhe sua ponte com vão de 20 cm","Monte as laterais com triângulos","Una as laterais","Espere a cola secar","Teste com pesos aos poucos","Fotografe e compartilhe"],"points":50}'::jsonb),
